"""Shared native growable-font source; configured limits remain authoritative."""
import re

_HEADER = '#ifndef SIGLUM_FONT_MEMORY_H\n#define SIGLUM_FONT_MEMORY_H\nint siglum_font_memory_configure(int words);\nvoid siglum_font_memory_begin(void);\nint siglum_font_memory_reserve(long long words);\nint siglum_font_memory_capacity(void);\nint siglum_font_memory_limit(void);\nint siglum_font_memory_growth_count(void);\n#endif\n'
_IMPLEMENTATION = '/* The configured font_mem_size remains the upper bound. Only allocation\n * capacity grows. TeX stores font metrics by index; the sole global pointer\n * is rebound before the new metric is read. No second TeX heap is created. */\n#include <stdlib.h>\nstatic int siglum_font_limit_value = 0;\nstatic int siglum_font_growths_value = 0;\nstatic int siglum_font_initial_value = 1000000;\nstatic int siglum_font_initialized = 0;\nint siglum_font_memory_configure(int words) {\n    if (siglum_font_initialized || words < 0 || (words > 0 && words < 100000)) return -1;\n    siglum_font_initial_value = words;\n    return 0;\n}\nvoid siglum_font_memory_begin(void) {\n    int initial = siglum_font_initial_value;\n    siglum_font_initialized = 1;\n    siglum_font_limit_value = fontmemsize;\n    siglum_font_growths_value = 0;\n    if (initial > 0 && initial < fontmemsize) fontmemsize = (integer)initial;\n}\nint siglum_font_memory_reserve(long long words) {\n    long long capacity;\n    /* Loading a format may raise the minimum above a configured capacity. */\n    if (fontmemsize > siglum_font_limit_value) siglum_font_limit_value = fontmemsize;\n    if (words <= fontmemsize) return words >= 0;\n    if (words > siglum_font_limit_value) return 0;\n    capacity = (long long)fontmemsize * 2;\n    if (capacity < words) capacity = words;\n    if (capacity > siglum_font_limit_value) capacity = siglum_font_limit_value;\n    fontinfo = (fmemoryword *)xrealloc(fontinfo, ((size_t)capacity + 1) * sizeof(fmemoryword));\n    fontmemsize = (integer)capacity;\n    siglum_font_growths_value++;\n    return 1;\n}\nint siglum_font_memory_capacity(void) { return fontmemsize; }\nint siglum_font_memory_limit(void) { return siglum_font_limit_value; }\nint siglum_font_memory_growth_count(void) { return siglum_font_growths_value; }\n'

def font_memory_source(prefix='siglum_font'):
    if not re.fullmatch(r'[a-z][a-z0-9_]*',prefix):raise ValueError('Invalid native font namespace')
    return (_HEADER.replace('siglum_font',prefix).replace('SIGLUM_FONT',prefix.upper()),
            _IMPLEMENTATION.replace('siglum_font',prefix))
